const test = require('node:test');
const assert = require('node:assert/strict');
const { complete } = require('../badge.cjs');
test('all three badge fields are required', () => {
  const valid = Object.freeze({ name:'周敏', company:'Harbor', host:'Rui', floor:2 });
  assert.equal(complete(valid), true);
  assert.equal(complete({}), false);
  for (const key of ['name','company','host']) {
    const missing = {...valid}; delete missing[key];
    assert.equal(complete(missing), false);
    for (const value of ['','  	',null,0,false]) {
      assert.equal(complete({...valid,[key]:value}), false);
    }
  }
  assert.equal(complete({name:' Li ',company:' Pier ',host:' Chen '}), true);
});

test('checking a mutable badge leaves every original field intact', () => {
  for (const [record,expected] of [
    [{name:' Li ',company:' Pier ',host:' Chen ',floor:2},true],
    [{name:' Li ',company:' Pier ',host:' \t\n',extra:'untouched'},false]
  ]) {
    const before = structuredClone(record);
    assert.equal(complete(record),expected);
    assert.deepEqual(record,before);
  }
  assert.equal(complete({name:'Li',company:'Pier',host:'Chen',other:null}),true);
  for (const key of ['name','company','host']) {
    assert.equal(complete({name:'Li',company:'Pier',host:'Chen',[key]:'\r\n\u3000'}),false);
  }
});

